        "teluguSpeak": "பயந்தோ வணிகின எலுக, 'ராஜா, நன்னு க்ஷமிஞ்சி வதிலேண்டி!' அனி வேடுகொந்தி.",
        "teluguScript": "భయంతో వణికిన ఎలుక, 'రాజా, నన్ను క్షమించి వదిలేయండి!' అని వేడుకుంది.",
        "teluguSub": "Bhayamtho vanikina eluka, 'Raajaa, nannu kshaminchi vadileyandi!' ani vedukondi.",
        "kannadaSpeak": "பயதிந்த நடுகித இலி, 'மஹாராஜரே, நன்னன்னு க்ஷமிசி பிடி!' என்று பேடிது.",
        "kannadaScript": "ಭಯದಿಂದ ನಡುಗಿದ ಇಲಿ, 'ಮಹಾರಾಜರೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸಿ ಬಿಡಿ!' ಎಂದು ಬೇಡಿತು.",
        "kannadaSub": "Bhayadinda nadugida ili, 'Mahaaraajare, nannannu kshamisi bidi!' endu beditu.",
        "hindiSpeak": "டர் சே காம்ப்தே ஹுயே சூஹே நே கஹா, 'ஹே மகாராஜ், முஜே மாஃப் கர் தீஜியே ஔர் சோட் தீஜியே!'",
        "hindiScript": "डर से कांपते हुए चूहे ने कहा, 'हे महाराज, मुझे माफ कर दीजिए और छोड़ दीजिए!'",
        "hindiSub": "Dar se kaampte hue choohe ne kaha, 'Hey mahaaraaj, mujhe maaf kar deejiye aur chhod deejiye!'"
