        "tamil": "'என்றாவது ஒரு நாள் நான் தங்களுக்கு ஒரு உதவி செய்வேன்' என்று சுண்டெலி பணிவுடன் கூறியது.",
        "english": "'Someday in the future, I promise I will definitely help you in return,' the mouse promised.",
        "teluguSpeak": "'எப்போதோ ஒகரோஜு நேனு மீக்கு தப்பகுண்டா சஹாயம் சேஸ்தானு' அனி வினயம்கா செப்பிந்தி.",
        "teluguScript": "'ఎప్పుడో ఒకరోజు నేను మీకు తప్పకుండా సహాయం చేస్తాను' అని వినయంగా చెప్పింది.",
