        "kannadaScript": "'ಯಾವಾಗಲಾದರೂ ಒಂದು ದಿನ ನಾನು ನಿಮಗೆ ಖಂಡಿತವಾಗಿಯೂ ಸಹಾಯ ಮಾಡುವೆನೆ' ಎಂದು ವಿನಯದಿಂದ ಹೇಳಿತು.",
        "kannadaSub": "'Yaavaagalaadaroo ondu dina naanu nimage khandithavaagiyoo sahaaya maaduvene' endu vinayadinda helitu.",
