        "hindiScript": "'कभी न कभी मैं भी आपकी मदद जरूर करूँगा,' चूहे ने विनम्रता से कहा.",
        "hindiSub": "'Kabhee na kabhee main bhi aapki madad zaroor karoonga,' choohe ne vinamrataa se kaha."
