        "teluguScript": "ఈ చిన్న ఎలుక నాకు ఏమి సహాయం చేస్తుంది అనుకుని సింహం నవ్వింది.",
        "teluguSub": "Ee chinna eluka naaku emi sahaayam chesthundhi anukoni simham navvindi.",
