        "kannadaScript": "ಸ್ಪರ್ಧೆಯು ಆರಂಭವಾದ ಕೂಡಲೇ ಮೊಲವು ಮಿಂಚಿನ ವೇಗದಲ್ಲಿ ಮುನ್ನುಗ್ಗಿ ಬಹಳ ದೂರ ಹೋಯಿತು.",
