        "kannadaScript": "ಅರ್ಧ ದೂರ ಓಡಿದ ಮೊಲವು ಹಿಂದಕ್ಕೆ ನೋಡಿದಾಗ, ಆಮೆಯು ಬಹಳ ಹಿಂದೆ ಮೆಲ್ಲನೆ ಸಾಗಿರುವುದನ್ನು ಕಂಡಿತು.",
