        "kannadaScript": "'ಆಮೆ ಇಲ್ಲಿಗೆ ಬರಲು ಇನ್ನೂ ತುಂಬಾ ಸಮಯ ಬೇಕು, ಸ್ವಲ್ಪ ಹೊತ್ತು ನೆರಳಿನಲ್ಲಿ ಮಲಗೋಣ' ಎಂದುಕೊಂಡಿತು.",
        "kannadaSub": "'Aame illige baralu innoo tumbaa samaya beku, svalpa hottu neralinalli malagona' endukonditu.",
