        "hindiScript": "'कछुए को यहाँ आने में बहुत वक्त लगेगा, थोड़ी देर छाँव में सो लेते हैं,' खरगोश ने सोचा.",
        "hindiSub": "'Kachhue ko yahaan aane mein bahut waqt lagega, thodi der chhaanv mein so lete hain,' khargosh ne socha."
