        "kannadaScript": "ಒಂದು ದೊಡ್ಡ ಆಲದ ಮರದ ತಂಪಾದ ನೆರಳಿನಲ್ಲಿ ಮಲಗಿದ ಮೊಲವು ಗಾಢ ನಿದ್ರೆಯಲ್ಲಿ ಮುಳುಗಿತು.",
