        "teluguScript": "నిద్రపోతున్న కుందేలును దాటి తాబేలు శాంతంగా ముందుకు వెళ్లి గమ్యాన్ని చేరింది.",
        "teluguSub": "Nidrapothunna kundelunu daati thaabelu shaanthamgaa munduku velli gamyaanni cherindi.",
