        "kannadaScript": "ಮಲಗಿರುವ ಮೊಲವನ್ನು ದಾಟಿ ಆಮೆಯು ಶಾಂತವಾಗಿಯೇ ಪಂದ್ಯದ ಗೆರೆಯನ್ನು ತಲುಪಲು ಮುನ್ನುಗ್ಗಿತು.",
