        "hindiScript": "सोए हुए खरगोश को पीछे छोड़ते हुए कछुआ जीत की रेखा की ओर बढ़ता गया.",
        "hindiSub": "Soye hue khargosh ko peechhe chhodte hue kachhua jeet ki rekha ki ore badhta gaya."
