        "kannadaScript": "ಧಿಡೀರನೆ ಎಚ್ಚರವಾದ ಮೊಲವು ಸೂರ್ಯ ಮುಳುಗುತ್ತಿರುವುದನ್ನು ನೋಡಿ ಭಯದಿಂದ ಅಂತಿಮ ಗೆರೆಯ ಕಡೆಗೆ ಓಡಿತು.",
