        "kannadaScript": "ಕಟ್ಟಿಗೆಯವನು ಯಾವ ಆಸೆಯೂ ಇಲ್ಲದೆ, 'ತಾಯಿ, ಇದು ನನ್ನದಲ್ಲ' ಎಂದು ವಿನಯದಿಂದ ಹೇಳಿದನು.",
