        "teluguScript": "దేవత మళ్లీ నీటిలో మునిగి, ఈసారి ఒక అందమైన వెండి గొడ్డలిని తీసుకువచ్చింది.",
        "teluguSub": "Devatha mallee neetilo munigi, eesaari oka andamaina vendi goddalini teesukovacchindi.",
