        "kannadaScript": "ದೇವತೆಯು ಮತ್ತೆ ಹೊಳೆಯಲ್ಲಿ ಮುಳುಗಿ, ಈ ಬಾರಿ ಸುಂದರವಾದ ಬೆಳ್ಳಿಯ ಕೊಡಲಿಯನ್ನು ತಂದು ತೋರಿಸಿದಳು.",
