        "hindiScript": "देवी दूसरी बार नदी में गईं और इस बार एक सुंदर चाँदी की कुल्हाड़ी लेकर आईं.",
        "hindiSub": "Devee doosree baar nadee mein gayeem aur is baar ek sundar chaandee ki kulhaadee lekar aayeem."
