        "hindiScript": "चींटी धीरे से उस पत्ते पर चढ़ गई और सुरक्षित किनारे तक पहुँच गई.",
        "hindiSub": "Cheentee dheere se us patte par chadh gayee aur surakshit kinaare tak pahunch gayee."
