        "kannadaScript": "ಸಾವಿನ ದವಡೆಯಿಂದ ತನ್ನ ಜೀವವನ್ನು ಉಳಿಸಿದ ಪಾರಿವಾಳಕ್ಕೆ ಇರುವೆ ಮನತುಂಬಿ ಧನ್ಯವಾದ ಹೇಳಿತು.",
