        "teluguScript": "ఆ అరుపు విని మేల్కొన్న పావురం, ప్రమాదాన్ని గ్రహించి ఆకాశంలోకి ఎగిరిపోయింది.",
        "teluguSub": "Aa arupu vini melkonna paavuram, pramaadaanni grahinchi aakaashamloki egiripoyindi.",
