        "kannadaScript": "ಕಿರುಚಾಟವನ್ನು ಕೇಳಿ ಎಚ್ಚರವಾದ ಪಾರಿವಾಳವು, ಅಪಾಯವನ್ನು ಅರಿತು ತಕ್ಷಣವೇ ಆಕಾಶಕ್ಕೆ ಹಾರಿತು.",
