        "kannadaScript": "ಕೆಲವು ದಿನಗಳ ನಂತರ, ಆ ಹುಡುಗನು ಮತ್ತೆ 'ತೋಳ! ತೋಳ!' ಎಂದು ಸುಳ್ಳು ಕೂಗು ಹಾಕಿದನು.",
        "kannadaSub": "Kelavu dinagala nanthara, aa huduganu matthe 'Thola! Thola!' endu sullu koogu haakidanu.",
