        "teluguScript": "జనం ఈసారి కూడా పరుగెత్తుకుంటూ వచ్చారు; కుర్రాడు మళ్లీ వాళ్లను చూసి హేళనగా నవ్వాడు.",
        "teluguSub": "Janam eesaari koodaa parugetthukuntoo vacchaaru; kurraadu mallee vaallanu choosi helanagaa navvaadu.",
