        "kannadaScript": "ಜನರು ಈ ಬಾರಿಯೂ ಓಡಿ ಬಂದರು; ಹುಡುಗನು ಮತ್ತೊಮ್ಮೆ ಅವರನ್ನು ನೋಡಿ ಅಣಕಿಸಿ ನಕ್ಕನು.",
