        "hindiScript": "गाँववाले फिर से दौड़े आए; लड़का फिर से उन पर हँसा और मज़ाक उड़ाया.",
        "hindiSub": "Gaanvwaale phir se daude aaye; ladka phir se un par hansa aur mazaak udaaya."
