        "kannadaScript": "ಭಯದಿಂದ ನಡುಗಿದ ಹುಡುಗನು, 'ನಿಜವಾಗಿಯೂ ತೋಳ ಬಂದಿದೆ, ನನ್ನನ್ನು ಕಾಪಾಡಿ!' ಎಂದು ಕಣ್ಣೀರಿಟ್ಟು ಕಿರುಚಿದನು.",
