        "kannadaScript": "ಆದರೆ ಗ್ರಾಮಸ್ಥರು, ಅವನು ಮತ್ತೆ ಸುಳ್ಳು ಹೇಳಿ ಆಟವಾಡುತ್ತಿದ್ದಾನೆಂದು ಭಾವಿಸಿ ಯಾರೂ ಬರಲಿಲ್ಲ.",
