        "hindiSpeak": "காம்வ்வாலோன் நே சோசா கி வஹ் ஃபிர் சே ஜூட் போல் ரஹா ஹை, ஔர் கோயீ உஸ்கி மதத் கோ நஹீம் கயா.",
        "hindiScript": "गाँववालों ने सोचा कि वह फिर से झूठ बोल रहा है, और कोई उसकी मदद को नहीं गया.",
        "hindiSub": "Gaanvwaalon ne socha ki wah phir se jhooth bol raha hai, aur koyi uski madad ko nahin gaya."
