        "kannadaScript": "ಆ ಕ್ರೂರ ತೋಳವು ಹಲವಾರು ಕುರಿಗಳನ್ನು ಕೊಂದು ಎಳೆದೊಯ್ಯಿತು; ಹುಡುಗನು ಅಸಹಾಯಕನಾಗಿ ಅಳುತ್ತಿದ್ದನು.",
