        "tamil": "அப்போது தந்தை புன்னகையுடன், 'இப்போது அந்தக் கட்டை அவிழ்த்து விடுங்கள்' என்றார்.",
        "english": "Then the wise father smiled gently and said, 'Now untie the rope and separate the sticks.'",
