        "teluguScript": "అప్పుడు తండ్రి చిరునవ్వుతో, 'ఇప్పుడు ఆ కట్ట తాడును విప్పేయండి' అన్నాడు.",
        "teluguSub": "Appudu thandri chirunavvutho, 'Ippudu aa katta thaadunu vippeyandi' annaadu.",
