        "kannadaScript": "ಆಗ ತಂದೆಯು ಮಂದಹಾಸ ಬೀರುತ್ತಾ, 'ಈಗ ಆ ಕಟ್ಟನ್ನು ಬಿಚ್ಚಿ ಕಡ್ಡಿಗಳನ್ನು ಬೇರ್ಪಡಿಸಿ' ಎಂದನು.",
        "kannadaSub": "Aaga thandeyu mandahaasa beerutthaa, 'Eega aa kattannu bicchi kaddigalannu berpadisi' endanu.",
