        "tamil": "அவர் ஒவ்வொரு மகனின் கையிலும் ஒரே ஒரு குச்சியை மட்டும் கொடுத்து, 'இப்போது உடருங்கள்' என்றார்.",
        "english": "Handing each son just a single separate stick, he said, 'Now try breaking it.'",
