        "teluguScript": "అతను ఒక్కొక్కరి చేతికి ఒకే ఒక పుల్లను ఇచ్చి, 'ఇప్పుడు విరవండి' అన్నాడు.",
        "teluguSub": "Athanu okkokkari chethiki oke oka pullanu icchi, 'Ippudu viravandi' annaadu.",
