        "kannadaScript": "ಅವನು ಪ್ರತಿಯೊಬ್ಬರ ಕೈಗೂ ಒಂದೊಂದೇ ಕಡ್ಡಿಯನ್ನು ಕೊಟ್ಟು, 'ಈಗ ಮುರಿಯಿರಿ' ಎಂದನು.",
