        "teluguScript": "నలుగురు కొడుకులు చాలా సులభంగా ఆ ఒంటి పుల్లలను క్షణంలో విరిచివేశారు.",
        "teluguSub": "Naluguru kodukulu chaalaa sulabhamgaa aa onti pullalanu kshanamlo virichiveshaaru.",
