        "kannadaScript": "ನಾಲ್ಕೂ ಮಂದಿ ಮಕ್ಕಳು ತಮ್ಮ ಕೈಯಲ್ಲಿದ್ದ ಒಂದೊಂದು ಕಡ್ಡಿಯನ್ನು ಕ್ಷಣಮಾತ್ರದಲ್ಲಿ ಮುರಿದರು.",
