        "english": "'Do you see? If you four stay united together, no enemy in this world can ever harm you,' said the father.",
        "teluguSpeak": "'சூசரா? மீரு நால்குரூ ஐகமத்யம்கா உந்தே, எவரி வலனா கூடா மீமி ஏமீ சேயலேரு' அன்னாடு தண்ட்ரி.",
