        "english": "This profound demonstration opened the eyes and softened the hearts of all four brothers.",
        "teluguSpeak": "தண்ட்ரி செப்பின ஈ உபதேசம் நால்குரு கொடுகுல கன்னுலனு தெரிபிஞ்சிந்தி.",
        "teluguScript": "తండ్రి చెప్పిన ఈ గుణపాఠం నలుగురు కొడుకుల కళ్లు తెరిపించి మనసు మార్చింది.",
