        "english": "From that day onwards, they renounced discord, lived in solid harmony, and prospered together.",
        "teluguSpeak": "ஆ ரோஜு நுண்டி வாரு தகாதாலனு மர்ச்சிபோயி, ஐகமத்யம்கா ஜீவிஸ்தூ குடும்பானிஸ்கி கௌரவம் தெச்சாரு.",
