        "kannadaScript": "ಆ ದಿನದಿಂದ ಅವರು ದ್ವೇಷವನ್ನು ಮರೆತು, ಒಗ್ಗಟ್ಟಿನಿಂದ ಪ್ರೀತಿಯಿಂದ ಬಾಳಿ ಕುಟುಂಬವನ್ನು ಉತ್ತುಂಗಕ್ಕೆ ಕೊಂಡೊಯ್ದರು.",
