        "teluguScript": "అది నోరు తెరిచిన మరుక్షణంలోనే, నోట్లో ఉన్న ఎముక ముక్క జారి నీటిలో పడిపోయింది.",
        "teluguSub": "Adi noru therichina marukshanamlone, notlo unna emuka mukka jaari neetilo padipoyindi.",
