        "kannadaScript": "ಒಂದು ದೊಡ್ಡ ಹೊಳೆಯ ದಂಡೆಯ ನೇರಳೆ ಮರದಲ್ಲಿ ಒಂದು ಬುದ್ಧಿವಂತ ಕೋತಿಯು ವಾಸಿಸುತ್ತಿತ್ತು.",
