        "english": "When they reached the deepest waters, the guilt-ridden crocodile revealed the treacherous plot.",
        "teluguSpeak": "ஏரு மத்யலோனி லோத்தமைன பிராந்தானிஸ்கி சேரகானே, முதலெ தன பார்ய க்ரூர யோசனனு செப்பிந்தி.",
        "teluguScript": "ఏరు మధ్యలోని లోతైన ప్రాంతానికి చేరుకోగానే, మొసలి తన భార్య యొక్క క్రూరమైన పథకాన్ని వెల్లడించింది.",
