        "kannadaScript": "ಹೊಳೆಯ ಮಧ್ಯದ ಆಳವಾದ ಜಾಗಕ್ಕೆ ಬಂದಾಗ, ಮೊಸಳೆಯು ತನ್ನ ಹೆಂಡತಿಯ ದುಷ್ಟ ಉದ್ದೇಶವನ್ನು ಹೇಳಿಬಿಟ್ಟಿತು.",
