        "hindiScript": "नदी के गहरे बीचों-बीच पहुँच कर, मगरमच्छ ने अपनी पत्नी का असली इरादा बता दिया.",
        "hindiSub": "Nadee ke gahre beechon-beech pahunch kar, magarmachh ne apni patni ka aslee iraada bata diya."
