        "english": "'Oh dear friend! Why did you not say so earlier? I safely left my heart back on the jamun tree!' cried the monkey.",
        "teluguSpeak": "'அய்யோ மித்ருடா! நா குண்டெனி செட்டு கொம்மலோனே பத்திரம்கா தாசி வச்சானே!' அனிந்தி.",
