        "kannadaScript": "'ಅಯ್ಯೋ ಗೆಳೆಯನೇ! ನನ್ನ ಹೃದಯವನ್ನು ಮರದ ಕೊಂಬೆಯ ಮೇಲೆಯೇ ಭದ್ರವಾಗಿ ಬಿಟ್ಟು ಬಂದಿದ್ದೇನಲ್ಲಾ!' ಎಂದಿತು.",
