        "kannadaScript": "ಮೂರ್ಖ ಮೊಸಳೆಯು ಅದನ್ನು ನಂಬಿ ದಂಡೆಗೆ ಮರಳಿದ ಕೂಡಲೇ, ಕೋತಿಯು ಮರದ ಕೊಂಬೆಗೆ ಜಿಗಿದು ಪ್ರಾಣ ಉಳಿಸಿಕೊಂಡಿತು.",
        "kannadaSub": "Moorkha mosaleyu adannu nambi dandege maralida koodale, kothiyu marada kombege jigidu praana ulisikonditu.",
