        "kannadaScript": "'ದ್ರೋಹಿಯೇ! ಹೃದಯವು ದೇಹದೊಳಗೆ ಇರುತ್ತದೆ; ಇನ್ನೆಂದೂ ನಿನ್ನ ಸ್ನೇಹವೇ ಬೇಡ!' ಎಂದು ಹೇಳಿ ಪಾರಾಯಿತು.",
        "kannadaSub": "'Drohiye! Hrudayavu dehadolage irutthade; innendoo ninna snehave beda!' endu heli paaraayithu.",
        "hindiSpeak": "'தோகேபாஜ்! தில் சரீர் கே அந்தர் ஹீ ஹோதா ஹை; அப் முஜே தும் ஜைசே தோஸ்த் கீ ஜரூரத் நஹீம்!' கஹகர் பந்தர் பச் கயா.",
        "hindiScript": "'धोखेबाज़! दिल शरीर के अंदर ही होता है; अब मुझे तुम जैसे दोस्त की ज़रूरत नहीं!' कहकर बंदर बच गया.",
